from pathlib import Path
from PIL import Image, ImageDraw, ImageFont
import subprocess, textwrap, shutil, base64, io

W, H, FPS = 512, 910, 24
BG = "#0F1114"
FG = "#F2F2F2"
LIME = "#C6FF00"
GRAY700 = "#2A2D31"
GRAY500 = "#6B6F76"

OUT = Path("output")
FR = OUT / "frames"
OUT.mkdir(exist_ok=True)
FR.mkdir(exist_ok=True)

LOGO_B64 = """"""

SCENES = [
    (0.00, 9.75, "QUESTION"),
    (9.75, 21.00, "CASE"),
    (21.00, 28.30, "SCALE"),
    (28.30, 40.20, "TENSION"),
    (40.20, 53.20, "TRADEOFF"),
    (53.20, 61.70, "DECISION"),
    (61.70, 70.00, "NOWWHAT"),
]

def font(size=28, bold=False):
    candidates = [
        "/usr/share/fonts/truetype/inter/Inter-Bold.ttf" if bold else "/usr/share/fonts/truetype/inter/Inter-Regular.ttf",
        "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf" if bold else "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
    ]
    for p in candidates:
        if Path(p).exists():
            return ImageFont.truetype(p, size)
    return ImageFont.load_default()

F16 = font(16)
F18 = font(18)
F20B = font(20, True)
F24 = font(24)
F27 = font(27)
F30B = font(30, True)
F36B = font(36, True)
F44B = font(44, True)
F54B = font(54, True)

def wrap(draw, text, x, y, fnt, fill=FG, width=30, gap=8, max_y=790):
    for line in textwrap.wrap(text, width=width):
        if y > max_y:
            break
        draw.text((x, y), line, font=fnt, fill=fill)
        box = draw.textbbox((x, y), line, font=fnt)
        y = box[3] + gap
    return y

def add_identity(img, end=False):
    logo = Image.open(io.BytesIO(base64.b64decode(LOGO_B64))).convert("RGBA")
    if end:
        target_w = 390
        ratio = target_w / logo.width
        logo = logo.resize((target_w, int(logo.height*ratio)), Image.Resampling.LANCZOS)
        img.alpha_composite(logo, (61, 716))
    else:
        target_w = 205
        ratio = target_w / logo.width
        logo = logo.resize((target_w, int(logo.height*ratio)), Image.Resampling.LANCZOS)
        img.alpha_composite(logo, (34, 34))

def canvas(end=False):
    img = Image.new("RGBA", (W, H), BG)
    add_identity(img, end=end)
    return img

def footer(d):
    d.line((34, 842, 478, 842), fill=GRAY700, width=2)
    d.text((34, 858), "DECISION SHORT", font=F16, fill=GRAY500)

def scene_question():
    img = canvas(); d = ImageDraw.Draw(img)
    d.rounded_rectangle((34, 142, 43, 308), radius=4, fill=LIME)
    d.text((64, 145), "DECISION QUESTION", font=F20B, fill=LIME)
    text = "Quando acquisisci una piattaforma che vale perché è neutrale, come ottieni i benefici del controllo senza distruggere la fiducia che ne alimenta il valore?"
    wrap(d, text, 64, 205, F36B, width=22, gap=12, max_y=790)
    footer(d); return img

def scene_case():
    img = canvas(); d = ImageDraw.Draw(img)
    d.text((34, 150), "THE CASE", font=F20B, fill=LIME)
    d.text((34, 210), "NVIDIA", font=F44B, fill=FG)
    d.text((34, 268), "→ HUGGING FACE", font=F30B, fill=FG)
    d.text((34, 365), "$12.93B", font=F54B, fill=LIME)
    d.text((34, 430), "agreed acquisition", font=F24, fill=GRAY500)
    d.line((34, 515, 478, 515), fill=GRAY700, width=2)
    wrap(d, "Infrastructure strength meets an open ecosystem.", 34, 550, F27, width=29, gap=10)
    footer(d); return img

def scene_scale():
    img = canvas(); d = ImageDraw.Draw(img)
    d.text((34, 150), "WHO / WHAT / SCALE", font=F20B, fill=LIME)
    d.text((34, 225), "18M+", font=F54B, fill=FG)
    d.text((34, 287), "developers", font=F24, fill=GRAY500)
    d.text((34, 405), "200K+", font=F54B, fill=FG)
    d.text((34, 467), "companies", font=F24, fill=GRAY500)
    d.line((300, 220, 300, 525), fill=GRAY700, width=2)
    wrap(d, "Open platform serving models, clouds and processors across the AI ecosystem.", 328, 225, F24, width=12, gap=9)
    footer(d); return img

def scene_tension():
    img = canvas(); d = ImageDraw.Draw(img)
    d.text((34, 150), "THE TENSION", font=F20B, fill=LIME)
    d.text((34, 232), "OWNER BENEFIT", font=F20B, fill=FG)
    wrap(d, "Infrastructure\nReliability\nDistribution", 34, 282, F27, width=18, gap=11)
    d.line((255, 220, 255, 650), fill=GRAY700, width=2)
    d.text((282, 232), "PLATFORM VALUE", font=F20B, fill=FG)
    wrap(d, "Choice\nInteroperability\nNeutrality", 282, 282, F27, width=16, gap=11)
    d.rounded_rectangle((34, 700, 478, 770), radius=12, outline=LIME, width=2)
    d.text((57, 720), "CONTROL ≠ AUTOMATIC VALUE", font=F20B, fill=LIME)
    footer(d); return img

def scene_tradeoff():
    img = canvas(); d = ImageDraw.Draw(img)
    d.text((34, 150), "WHAT TO INTEGRATE", font=F20B, fill=LIME)
    wrap(d, "Infrastructure • Security • Investment capacity", 34, 205, F30B, width=24, gap=12)
    d.line((34, 390, 478, 390), fill=GRAY700, width=2)
    d.text((34, 438), "WHAT MUST STAY CREDIBLY NEUTRAL", font=F18, fill=LIME)
    wrap(d, "Access • Interoperability • Freedom of choice", 34, 495, F30B, width=24, gap=12)
    d.text((34, 735), "Separate the control layer from the trust layer.", font=F18, fill=GRAY500)
    footer(d); return img

def scene_decision():
    img = canvas(); d = ImageDraw.Draw(img)
    d.text((34, 150), "DECISION", font=F20B, fill=LIME)
    d.rounded_rectangle((34, 215, 478, 665), radius=18, outline=GRAY700, width=2)
    d.rounded_rectangle((34, 215, 43, 665), radius=4, fill=LIME)
    text = "Il controllo crea valore soltanto se non compromette il motivo per cui utenti e partner partecipano alla piattaforma."
    wrap(d, text, 68, 270, F36B, width=21, gap=13, max_y=620)
    d.text((34, 720), "Governance must make the separation verifiable.", font=F18, fill=GRAY500)
    footer(d); return img

def scene_nowwhat():
    img = canvas(end=True); d = ImageDraw.Draw(img)
    d.text((34, 145), "NOW WHAT", font=F20B, fill=LIME)
    d.text((34, 210), "MEASURE BOTH", font=F44B, fill=FG)
    d.text((34, 315), "1", font=F44B, fill=LIME)
    wrap(d, "Benefits of integration", 95, 320, F27, width=23, gap=9)
    d.text((34, 445), "2", font=F44B, fill=LIME)
    wrap(d, "Continuity of real choice", 95, 450, F27, width=23, gap=9)
    d.line((34, 585, 478, 585), fill=GRAY700, width=2)
    wrap(d, "Growth is not enough if neutrality erodes.", 34, 620, F24, fill=GRAY500, width=31, gap=9)
    return img

FACTORIES = [scene_question, scene_case, scene_scale, scene_tension, scene_tradeoff, scene_decision, scene_nowwhat]

if not shutil.which("ffmpeg"):
    raise SystemExit("ffmpeg not found")

items = []
for i, (start, end, _) in enumerate(SCENES):
    p = FR / f"scene_{i:02d}.png"
    FACTORIES[i]().convert("RGB").save(p, quality=95)
    items.append((p, end-start))

concat = OUT / "concat.txt"
with concat.open("w", encoding="utf-8") as f:
    for p, dur in items:
        f.write(f"file '{p.resolve()}'\n")
        f.write(f"duration {dur:.6f}\n")
    f.write(f"file '{items[-1][0].resolve()}'\n")

visual = OUT / "DecisionOS_M0103_NVIDIA_VISUAL_V2.mp4"
subprocess.run([
    "ffmpeg","-y","-f","concat","-safe","0","-i",str(concat),
    "-vf",f"fps={FPS},format=yuv420p",
    "-c:v","libx264","-pix_fmt","yuv420p","-movflags","+faststart",
    str(visual)
], check=True)

print(visual)
